# Generated by manage.py generate_test_cases.
"""Exercise the persistent deduplication key for verified webhook events."""

from typing import Any

from django.core.exceptions import ValidationError
from django.utils import timezone

from bloomerp.models.communication.conferencing import ConferenceWebhookReceipt
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)


class TestConferenceWebhookReceiptModel(BloomerpModelTestCase):
    model = ConferenceWebhookReceipt

    def get_test_scenarios(self) -> list[ModelScenario[ConferenceWebhookReceipt]]:
        """Cover durable event IDs and rejection of duplicate deliveries."""
        return [
            ModelScenario(
                name="Record verified event receipt", create_args=self.receipt_args
            ),
            ModelScenario(
                name="Reject duplicate webhook ID",
                preparation=self.existing_receipt,
                create_args=self.receipt_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Event identity cannot change",
                create_args=self.receipt_args,
                update_args={"event_id": "other-event"},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
        ]

    def receipt_args(self) -> dict[str, Any]:
        """Describe a verified provider event without storing its raw body."""
        return {
            "event_id": "EV_unique",
            "event_type": "room_started",
            "occurred_at": timezone.now(),
        }

    def existing_receipt(self) -> None:
        """Persist the first delivery of an event before replaying its ID."""
        ConferenceWebhookReceipt.objects.create(**self.receipt_args())
